-- =====================================================
-- sql-skill-push: retail dataset (PostgreSQL)
-- Deterministic seed-generated data. Run as a single script.
-- =====================================================

DROP TABLE IF EXISTS "products";
DROP TABLE IF EXISTS "customers";
DROP TABLE IF EXISTS "orders";
DROP TABLE IF EXISTS "order_items";

-- =====================================================
-- BUSINESS CONTEXT (short)
-- Brew & Co., a 3-branch coffee shop chain. Tables: products, customers, orders, order_items.
-- =====================================================

CREATE TABLE "products" (
    "prod_id" VARCHAR(6) PRIMARY KEY,
    "prod_name" VARCHAR(60),
    "category" VARCHAR(20),
    "unit_price" DECIMAL(8,2),
    "is_active" SMALLINT
);

CREATE TABLE "customers" (
    "cust_id" VARCHAR(6) PRIMARY KEY,
    "first_name" VARCHAR(30),
    "last_name" VARCHAR(30),
    "email" VARCHAR(80),
    "city" VARCHAR(40),
    "signup_date" DATE,
    "loyalty_points" INT
);

CREATE TABLE "orders" (
    "order_id" INT PRIMARY KEY,
    "order_date" DATE,
    "customer_id" VARCHAR(6),
    "store_id" VARCHAR(6),
    "payment_method" VARCHAR(12),
    "total_amount" DECIMAL(8,2)
);

CREATE TABLE "order_items" (
    "item_id" INT PRIMARY KEY,
    "order_id" INT,
    "product_id" VARCHAR(6),
    "quantity" INT,
    "unit_price" DECIMAL(8,2)
);

